def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = n - opp.count('D')

    if n == 2:
        if opp[-1] == 'D':
            return 'D'
        return 'C'

    if n < 5:
        if opp[-1] == 'D':
            return 'D'
        return 'C'

    last_o = opp[-1]
    last_m = me[-1]

    # last few opponent actions
    look = 6 if n >= 6 else n
    rec_d = 0
    for i in range(n - look, n):
        if opp[i] == 'D':
            rec_d += 1

    # Strong punishment window
    if n >= 3 and opp[-3:] == ['D', 'D', 'D']:
        return 'D'

    if rec_d >= 3:
        if n >= 8 and opp[-8:].count('D') >= 6:
            return 'D'
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Cooperative reset: if opponent has just played two C after trouble, cooperate
    if n >= 3 and opp[-1] == 'C' and opp[-2] == 'C' and opp[-3] == 'D':
        return 'C'

    if last_o == 'D':
        # Retaliate but sometimes offer olive branch
        if n >= 5 and opp[-5:].count('D') >= 3:
            return 'D'
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Endgame exploitation: last few rounds
    remaining = 100 - n
    if remaining <= 2:
        if opp_c * 4 >= n * 3 or (n >= 5 and opp[-5:].count('C') >= 4):
            return 'C'
        return 'D'

    if remaining <= 5:
        if last_o == 'D':
            return 'D'
        if opp_c * 3 >= n * 2:
            return 'C'
        return 'D'

    if last_m == 'D' and last_o == 'C':
        # We just exploited; do not continue unless opponent is very forgiving
        return 'C'

    # Anti-exploitation: if opponent defects a lot overall
    if n >= 10:
        ratio_d = opp.count('D') / n
        if ratio_d > 0.5:
            if n >= 5 and opp[-5:].count('C') >= 3:
                return 'C'
            return 'D' if rng.random() < 0.85 else 'C'
        if ratio_d < 0.1:
            return 'C'

    # Occasionally probe against very cooperative opponent to gain DC
    if n >= 12:
        if opp_c * 10 >= n * 9 and n % 13 == 0:
            return 'D'

    # Default forgiveness/tit-for-tat cooperative stance
    if n >= 4 and opp[-4:].count('D') <= 1:
        return 'C'

    if rec_d >= 2:
        return 'D' if rng.random() < 0.7 else 'C'

    return 'C'
